const root = '/Users/harshodaikolluru/Public/askmukthiguru-8119b0e8';
const schema = JSON.stringify({
  type: 'object',
  properties: {
    area: {type: 'string'},
    summary: {type: 'string'},
    findings: {type: 'array', items: {type: 'object', properties: {
      id: {type: 'string'}, severity: {type: 'string'}, title: {type: 'string'},
      evidence: {type: 'string'}, impact: {type: 'string'}, confidence: {type: 'string'},
      recommended_next_step: {type: 'string'}, verification_needed: {type: 'string'},
      source_paths: {type: 'array', items: {type: 'string'}}
    }, required: ['id','severity','title','evidence','impact','confidence','recommended_next_step','verification_needed','source_paths']}},
    positive_controls: {type: 'array', items: {type: 'string'}},
    open_questions: {type: 'array', items: {type: 'string'}}
  },
  required: ['area','summary','findings','positive_controls','open_questions']
});
const files = [
  {path: root + '/AGENTS.md', name: 'repo_invariants'},
  {path: root + '/.claude/tasks/backend-ruthless-product-audit-2026-10-27.md', name: 'approved_audit_plan'},
  {path: root + '/lessons.md', name: 'repository_lessons'}
];
const tasks = [
  {id:'ingestion-data-engineering', brief:'Audit ingestion and corpus engineering', scope:'Trace backend source→extract→quality gate→chunk/enrich→embed→Qdrant/graph→publication and lifecycle. Verify actual implementation and tests for provenance, rights, rejection accounting, idempotency, lineage, writer/reader schema compatibility and safe rebuilds. Cross-check the existing plan at .claude/tasks/2026-10-25-rag-data-platform-master-plan.md and .claude/tasks/2026-10-25-first-person-data-engineering-audit.md; treat them as hypotheses, not proof.'},
  {id:'qdrant-retrieval-contracts', brief:'Audit Qdrant retrieval and data contracts', scope:'Trace active Qdrant query paths, vector/sparse schemas, filters, payload indexes, hybrid fusion, grouping, reranking and relevant collection contracts in code. Use the installed official qdrant-advisor skill and current skills.qdrant.tech material, following its search-quality branch. Known runtime baseline: local Docker Qdrant 1.18.0, healthy, 19 collections; first_person alias targets first_person_v10. Do not access raw live payloads or write to Qdrant. Separate code findings from runtime data findings.'},
  {id:'rag-okf-answer-paths', brief:'Audit general RAG and OKF answer paths', scope:'Map the actual backend answer graph, retrieval branches, graph/LightRAG and OKF use, query rewriting/decomposition, context selection/compression, citations/verification, terminal fallbacks and abstention/safety order. Verify reachable paths and tests, including where an answer bypasses quality gates. Do not tune thresholds or change implementation.'},
  {id:'first-person-serving-safety', brief:'Audit first-person serving and safety gates', scope:'Inspect the complete first-person ingest/serve/context-harness path, speaker evidence, timing/schema, rights register, corpus tiers, cache fingerprint, weak-match/directness labeling, enrichment/graph expansion and crisis/error handling. Respect every NO-GO invariant: no flag/alias/collection/Qdrant/Redis/deployment/Railway mutation. Current uncommitted edits in first-person source/tests are user-owned; do not edit or claim them as yours. Cross-check .claude/tasks/2026-10-25-first-person-data-engineering-audit.md and report what the current code actually proves.'},
  {id:'ops-security-resilience', brief:'Audit backend operations and security', scope:'Read-only review of backend API auth/session/rate limits, tenant boundaries, privacy/logging, cache/queue failure behavior, startup guards, compose wiring, observability/alerts, timeouts/retries and backup/restore controls. Trace concrete source paths and relevant tests. Do not print secrets, run destructive commands, change configuration, or claim production status from local files.'},
  {id:'evaluation-and-test-gates', brief:'Audit answer evaluation and regression gates', scope:'Inspect existing eval harnesses, golden datasets, query-class coverage, retrieval ranking metrics, citation/faithfulness checks, safety/abstention measures, CI triggers and test execution boundaries. Identify exactly what current measurements establish versus what they cannot establish. Do not run live chat sweeps, tune metrics, or change tests.'}
];
const mapped = await parallel('Six backend product audit modules', () => tasks.map((task, index) => agent(
  'Audit exactly this backend module in read-only mode.\nRepo root: ' + root + '\nModule: ' + task.id + '\nScope: ' + task.scope + '\n\nConstraints: Follow repo_invariants and approved_audit_plan. Inspect the shared workspace code, tests, and documentation. Do not edit files, call admin/write APIs, run Docker or migration/ingestion scripts, mutate data, or tune thresholds. Do not expose secrets or raw transcript payloads. Use exact repo-relative file:line evidence for material claims; trace call paths instead of relying on name-grep. Classify severity P0/P1/P2/P3 and confidence high/medium/low. Clearly mark anything not verified as unknown. Respect the known dirty working tree and distinguish uncommitted user changes. Return only JSON matching the shared schema.',
  {brief: task.brief, schema, input_files: files.concat(task.id === 'first-person-serving-safety' ? [{path: root + '/.claude/tasks/2026-10-25-first-person-data-engineering-audit.md', name: 'existing_first_person_plan'}] : task.id === 'ingestion-data-engineering' || task.id === 'qdrant-retrieval-contracts' || task.id === 'rag-okf-answer-paths' || task.id === 'evaluation-and-test-gates' ? [{path: root + '/.claude/tasks/2026-10-25-rag-data-platform-master-plan.md', name: 'existing_rag_plan'}] : []), sandbox: 'shared', effort_level: 'standard'}
)), {schema});
const successful = mapped.filter(x => x.ok).map(x => x.value);
const failures = mapped.map((x,i) => x.ok ? null : {item: tasks[i].id, code: x.error.code, message: x.error.message}).filter(Boolean);
let synthesis = null;
if (successful.length) {
  const reduced = await agent('Synthesize these completed backend audit module results only; do not perform new repository or web research.\n' + JSON.stringify(successful) + '\nReturn a concise evidence-grounded JSON synthesis with: top_risks (ranked, each with area, severity, evidence, impact and next verification), cross_module_conflicts, duplicate_or_already_planned_work, strong_controls, and items requiring parent runtime verification. Preserve uncertainty; do not turn recommendations into claims.', {
    brief: 'Synthesize backend audit findings',
    schema: JSON.stringify({type:'object',properties:{top_risks:{type:'array',items:{type:'object',properties:{area:{type:'string'},severity:{type:'string'},evidence:{type:'string'},impact:{type:'string'},next_verification:{type:'string'}},required:['area','severity','evidence','impact','next_verification']}},cross_module_conflicts:{type:'array',items:{type:'string'}},duplicate_or_already_planned_work:{type:'array',items:{type:'string'}},strong_controls:{type:'array',items:{type:'string'}},parent_runtime_verification:{type:'array',items:{type:'string'}}},required:['top_risks','cross_module_conflicts','duplicate_or_already_planned_work','strong_controls','parent_runtime_verification']}),
    input_files: [], sandbox:'shared', effort_level:'standard'
  });
  synthesis = reduced.ok ? reduced.value : {error: reduced.error};
}
return {results: successful, failures, synthesis};

